      "id": "batalha_s5D7Z3HAmoy5C1Zy",
      "title": "Our Song to War",
      "director": "Juanita Onzaga",
      "year": 2018,
      "duration": 14,
      "poster": "https://a.ltrbxd.com/resized/film-poster/4/4/8/5/3/6/448536-our-song-to-war-0-500-0-750-crop.jpg?v=e7ce9c814b",
